UPDATE courses SET
    course_description = '<html><body><p>The Master of Information Technology will equip students with the essential knowledge and skills that are relevant to any business to develop, implement and manage software products for commercial companies, software development companies, and government. Students will learn to manage multidisciplinary, data-driven Information Technology solutions, and develop meaningful approaches to continually evolving business applications, web-and-cloud-based systems and environments, choosing to specialise either in Business Analysis or Software Development.</p><p>The Master of Information Technology degree will equip students with advanced and integrated understanding of the complex body of knowledge in IT, with deep knowledge and skills in areas such as Cyber Security, Database Administration and Software Development, Information System Project Development and Management, Artificial Intelligence, Cloud Computing, and Internetof- Things. They will acquire advanced level of skills to practice independently their analytic and critical mindset, research, reflect on and synthesise complex information, problems, concepts and theories with the goal to apply established theories to a body of knowledge or practice in IT.</p><p>Graduates typically can work for commercial and government organisations in diverse industries, such as tourism, financial, health, retail, IT consulting or security providers nationally and internationality. Graduates at this level will be able to practice independently.</p> </body></html>',
    total_course_duration = '4 Semesters',
    offshore_tuition_fee = '40000',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/master-of-information-technology/',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '114019H';
UPDATE courses SET
    course_description = '<html><body><p>The Bachelor of Business (Cyber Security) is AAPoly’s newest degree and Australia’s first Bachelor degree in Cyber Security with a business focus. The course was designed to give students a broad business education with a significant amount of specialised Cyber Security training in Governance, Risk and Compliance (GRC). The students will be trained in the fundamentals of business as well as specialised training in GRC which will provide a solid foundation for broader roles within the Cyber Security business.</p><p>Through the program, the students will acquire high level career and work-ready skills in business economics, consumer behaviour, digital business communication, problem solving, negotiations, team building, organisational analytics and coherence strategic thinking skills in current and emerging Cyber Security practices within the enterprise. The degree will equip students with the skills and techniques required to align business risks with information security standards and governance frameworks, and manage multidisciplinary technological solutions to continually evolving Cyber Security threats and attacks.</p> </body></html>',
    total_course_duration = '6 Semesters',
    offshore_tuition_fee = '60000',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/bachelor-of-business-cyber-security/',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '110541M';
UPDATE courses SET
    course_description = '<html><body><p>The Bachelor of Business (Digital Marketing) is the newest AAPoly’s bachelor’s degree in digital marketing with a business focus. The course will equip students with the skills and techniques required to develop, implement and manage campaigns. Students will learn to manage multidisciplinary, data-driven digital marketing solutions, and develop meaningful approaches to continually evolving trends to measure and optimise traffic. The course will also prepare students to undertake relevant industry certifications, such as the Google Fundamentals of Digital Marketing certification.</p><p>Students will acquire high level career and work-ready skills in business economics, consumer behaviour, digital business communication, problem solving, negotiation, team building, organisational analysis and coherent strategic thinking in current and emerging Digital Marketing practices within an enterprise. Our experienced teaching staff will ensure readiness for different career roles in large, medium and small organisations, both in the private and government sectors.</p> </body></html>',
    total_course_duration = '6 Semesters',
    offshore_tuition_fee = '60000',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/bachelor-of-business-digital-marketing/',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '111272H';
UPDATE courses SET
    course_description = '<html><body><p>A Business Degree for Future Leaders</p><p>Do you see yourself making decisions that influence organisational direction? Business leaders need to know how to anticipate, formulate, resolve and communicate high-level strategies within an organisation. The Bachelor of Business (Leadership and Management) prepares students for specific managerial responsibilities. Students will be exposed throughout the course to contemporary industry practices and have the opportunity to engage with industry professionals. Students will study the theories, principles, processes and practices of strategic management, change management, business ethics and organisational analysis.</p><p>The Bachelor of Business (Leadership and Management) aims to equip students with high level career and work-ready skills in communication, problem solving, negotiation, team building, organisational analysis and strategic thinking skills. Students are prepared for careers in the management of large, medium and small organisations, in the private and government sectors, both domestically and internationally.</p> </body></html>',
    total_course_duration = '6 Semesters',
    offshore_tuition_fee = '60000',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/bachelor-of-business-leadership-and-management/',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '097316M';
