UPDATE courses SET
    course_description = '<html><body><p>The Bachelor of Tourism and Hospitality Management (BTHM) offers an effective starting point for a career in tourism and hospitality. The program is designed with an emphasis on case-based learning that builds progressively through the three year degree.</p><p>A feature of this BTHM program is the arrangement of practitioners as visiting lecturers who will share their knowledge and experience, and field trips to enable you to gain first-hand experience of the contemporary context of the tourism and hospitality sectors. These real-life case studies will support your learning and ensure you have a wide choice of work options and an increased potential for long-term career development and leadership roles in this dynamic growth industry.</p> </body></html>',
    total_course_duration = '6 Semesters',
    offshore_tuition_fee = '60000',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/bachelor-of-tourism-and-hospitality-management/',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '073530C';
UPDATE courses SET
    course_description = '<html><body><p><strong>Microsoft Cloud Partner Program:</strong></p><p>A partnership offering access to cloud-based technologies, tools, and resources. It’s instrumental for students in digital marketing, IT, cybersecurity, and management, providing them with the necessary tools to explore cloud-based solutions, enhance remote collaboration, and manage digital campaigns.</p><ul><li><a href="https://aapoly.edu.au/courses/bachelor-of-business-digital-marketing/">Bachelor of Business (Digital Marketing)</a>: Access to cloud-based technologies aids students in developing, implementing, and managing digital marketing campaigns.</li><li>ICT courses: All IT and cybersecurity degrees can benefit from this program, offering resources to explore cloud-based solutions and technologies.</li><li><a href="https://aapoly.edu.au/courses/bachelor-of-business-cyber-security/">Bachelor of Business (Cyber Security)</a>, Certificate IV in Information Technology, Advanced Diploma of Information Technology: Allows exploration of cloud-based security measures, adding a new dimension to cybersecurity courses.</li><li><a href="https://aapoly.edu.au/courses/int-leadership-management/">Diploma of Leadership and Management, Advanced Diploma of Leadership and Management</a>**: Offers tools and resources for efficient remote collaboration and management.</li><li><a href="https://aapoly.edu.au/courses/bachelor-of-business-analytics/">Bachelor of Business (Analytics)</a>: With cloud-based technologies becoming increasingly important for data storage and analysis, students in this program could benefit from resources to manage cloud-based analytics projects effectively.</li></ul> </body></html>',
    total_course_duration = '',
    offshore_tuition_fee = '0',
    entry_requirements = '',
    apply_form = 'https://aapoly.edu.au/courses/industry-partnerships',
    updated_at = '2026-06-26 12:27:59'
WHERE cricos_course_code = '02439G';
UPDATE courses SET
    course_description = '<html><body><p>The hospitality industry continues to grow with opportunities to expand a career in Australia and abroad. It is an exciting and a fast-paced industry with a wide range of sectors such as hotels, cruises, airlines, restaurants, bars and clubs.</p><p>This course will fast-track your career by preparing you with strong foundation of skills and practical knowledge needed to lead a service team and the understanding needed to thrive as a Chef/ Cook in a leading hotel, restaurant or other businesses within the hospitality and tourism industries.</p><p>On completion, graduates will have the knowledge and experience to work as Cook, Chef or Chef De Partie in a hospitality business.</p> </body></html>',
